import java.util.List;

public class FarmersMarketApp {
    public static void main(String[] args) {
        List<MarketProduct> products = List.of(
                new MarketProduct("Heirloom Tomatoes", "Green Acres", 4.50, "Vegetable", "Summer", true),
                new MarketProduct("Sweet Corn", "Miller Farm", 3.25, "Vegetable", "Summer", false),
                new MarketProduct("Honeycrisp Apples", "Hilltop Orchard", 5.75, "Fruit", "Fall", true),
                new MarketProduct("Goat Cheese", "Willow Creek Dairy", 8.00, "Dairy", "All", false),
                new MarketProduct("Wildflower Honey", "Bee Happy", 11.50, "Pantry", "All", true)
        );

        for (MarketProduct product : products) {
            System.out.println(product);
        }
    }
}
